## 23 STL常用算法

STL 提供了大量的算法，主要用于容器中的数据操作，例如查找、排序、拷贝、替换、算术生成和集合运算等。算法需要包含头文件 `#include <algorithm>`，算术生成算法需要 `#include <numeric>`，函数对象需要 `#include <functional>`。

> 注意：大多数算法都接受一对迭代器区间 [beg， end)，返回迭代器时如果没找到目标，一般返回 end() 或目标区间的结束位置。

### 23.1 常用遍历算法

#### 23.1.1 for_each

**作用**：遍历容器，把容器中的数据逐个传递给函数或函数对象处理。

**函数原型**：`for_each(iterator beg, iterator end, _func);`

**示例**：

```c++
#include <iostream>
using namespace std;
#include <vector>
#include <algorithm>

//普通函数
void print01(int val)
{
	cout << val << " ";
}

//函数对象
class print02
{
public:

	void operator()(int val)
	{
		cout << val << " ";
	}
};

void test01()
{
	vector<int> v;
	for (int i = 0; i < 10; i++)
	{
		v.push_back(i);
	}

	//普通函数
	for_each(v.begin(), v.end(), print01);
	cout << endl;

	//函数对象
	for_each(v.begin(), v.end(), print02());
	cout << endl;
}

int main() {

	test01();

	system("pause");

	return 0;
}
```

#### 23.1.2 transform

**作用**：搬运容器到另一个容器中，搬运过程中可以按函数规则变换数据。

**函数原型**：

* `transform(iterator beg1, iterator end1, iterator beg2, _func);`
* 二元运算版本：`transform(beg1, end1, beg2, target, _func);`

> 注意：目标容器需要**提前开辟空间**，否则会崩溃。

**示例**：

```c++
#include <iostream>
using namespace std;
#include <vector>
#include <algorithm>

//一元运算:搬运并取反? 这里是原样搬运
class Transform
{
public:

	int operator()(int v)
	{
		return v;
	}
};

//二元运算:两个容器对应元素相加
class Transform2
{
public:

	int operator()(int v1, int v2)
	{
		return v1 + v2;
	}
};

void test01()
{
	vector<int> v;
	for (int i = 0; i < 10; i++)
	{
		v.push_back(i);
	}

	vector<int> vTarget;
	//目标容器需要提前开辟空间
	vTarget.resize(v.size());

	transform(v.begin(), v.end(), vTarget.begin(), Transform());
}

void test02()
{
	vector<int> v1;
	for (int i = 0; i < 10; i++)
	{
		v1.push_back(i);
	}

	vector<int> v2;
	for (int i = 0; i < 10; i++)
	{
		v2.push_back(i + 100);
	}

	vector<int> vTarget;
	vTarget.resize(v1.size());

	transform(v1.begin(), v1.end(), v2.begin(), vTarget.begin(), Transform2());
}

int main() {

	test01();
	test02();

	system("pause");

	return 0;
}
```

### 23.2 常用查找算法

#### 23.2.1 find

**作用**：查找指定元素，找到返回指定元素的迭代器，找不到返回结束迭代器 end()。

**函数原型**：`find(iterator beg, iterator end, value);`

**示例**：

```c++
#include <iostream>
using namespace std;
#include <vector>
#include <algorithm>
#include <string>

//查找内置数据类型
void test01()
{
	vector<int> v;
	for (int i = 0; i < 10; i++)
	{
		v.push_back(i);
	}

	vector<int>::iterator it = find(v.begin(), v.end(), 5);

	if (it == v.end())
	{
		cout << "没有找到" << endl;
	}
	else
	{
		cout << "找到: " << *it << endl;
	}
}

//查找自定义数据类型
class Person
{
public:

	Person(string name, int age)
	{
		this->m_Name = name;
		this->m_Age = age;
	}

	//重载 == 让 find 知道如何比较 Person
	bool operator==(const Person& p)
	{
		return this->m_Name == p.m_Name && this->m_Age == p.m_Age;
	}

	string m_Name;
	int m_Age;
};

void test02()
{
	vector<Person> v;
	Person p1("aaa", 10);
	Person p2("bbb", 20);
	Person p3("ccc", 30);
	Person p4("ddd", 40);

	v.push_back(p1);
	v.push_back(p2);
	v.push_back(p3);
	v.push_back(p4);

	Person pp("bbb", 20);

	vector<Person>::iterator it = find(v.begin(), v.end(), pp);

	if (it == v.end())
	{
		cout << "没有找到" << endl;
	}
	else
	{
		cout << "找到姓名:" << it->m_Name << " 年龄:" << it->m_Age << endl;
	}
}

int main() {

	test01();
	test02();

	system("pause");

	return 0;
}
```

#### 23.2.2 find_if

**作用**：按条件查找元素，找到返回第一个满足条件的元素迭代器。

**函数原型**：`find_if(iterator beg, iterator end, _Pred);`

**示例**：

```c++
#include <iostream>
using namespace std;
#include <vector>
#include <algorithm>
#include <string>

//查找内置数据类型:找大于5的数
void test01()
{
	vector<int> v;
	for (int i = 0; i < 10; i++)
	{
		v.push_back(i);
	}

	//谓词:大于5
	class GreaterFive
	{
	public:
		bool operator()(int val)
		{
			return val > 5;
		}
	};

	vector<int>::iterator it = find_if(v.begin(), v.end(), GreaterFive());

	if (it == v.end())
	{
		cout << "没有找到" << endl;
	}
	else
	{
		cout << "找到大于5的数字:" << *it << endl;
	}
}

//查找自定义数据类型:找年龄大于20的人
class Person
{
public:

	Person(string name, int age)
	{
		this->m_Name = name;
		this->m_Age = age;
	}

	string m_Name;
	int m_Age;
};

class Greater20
{
public:

	bool operator()(Person& p)
	{
		return p.m_Age > 20;
	}
};

void test02()
{
	vector<Person> v;
	Person p1("aaa", 10);
	Person p2("bbb", 20);
	Person p3("ccc", 30);
	Person p4("ddd", 40);

	v.push_back(p1);
	v.push_back(p2);
	v.push_back(p3);
	v.push_back(p4);

	vector<Person>::iterator it = find_if(v.begin(), v.end(), Greater20());

	if (it == v.end())
	{
		cout << "没有找到" << endl;
	}
	else
	{
		cout << "找到姓名:" << it->m_Name << " 年龄:" << it->m_Age << endl;
	}
}

int main() {

	test01();
	test02();

	system("pause");

	return 0;
}
```

#### 23.2.3 adjacent_find

**作用**：查找**相邻重复**元素，返回相邻元素的第一个位置的迭代器。

**函数原型**：`adjacent_find(iterator beg, iterator end);`

**示例**：

```c++
#include <iostream>
using namespace std;
#include <vector>
#include <algorithm>

void test01()
{
	vector<int> v;
	v.push_back(10);
	v.push_back(20);
	v.push_back(30);
	v.push_back(30);
	v.push_back(40);

	vector<int>::iterator it = adjacent_find(v.begin(), v.end());

	if (it == v.end())
	{
		cout << "没有找到相邻重复元素" << endl;
	}
	else
	{
		cout << "找到相邻重复元素:" << *it << endl;
	}
}

int main() {

	test01();

	system("pause");

	return 0;
}
```

#### 23.2.4 binary_search

**作用**：查找指定元素是否存在，返回 **bool**。

> 注意：**必须在有序序列中**使用，无序序列会得到未知结果。

**函数原型**：`bool binary_search(iterator beg, iterator end, value);`

**示例**：

```c++
#include <iostream>
using namespace std;
#include <vector>
#include <algorithm>

void test01()
{
	vector<int> v;
	for (int i = 0; i < 10; i++)
	{
		v.push_back(i);
	}

	bool ret = binary_search(v.begin(), v.end(), 6);

	if (ret)
	{
		cout << "找到了" << endl;
	}
	else
	{
		cout << "未找到" << endl;
	}
}

int main() {

	test01();

	system("pause");

	return 0;
}
```

#### 23.2.5 count

**作用**：统计元素个数。

**函数原型**：`count(iterator beg, iterator end, value);`

**示例**：

```c++
#include <iostream>
using namespace std;
#include <vector>
