	test01();

	system("pause");

	return 0;
}
```

#### 23.2.5 count

**作用**：统计元素个数。

**函数原型**：`count(iterator beg, iterator end, value);`

**示例**：

```c++
#include <iostream>
using namespace std;
#include <vector>
#include <algorithm>
#include <string>

void test01()
{
	vector<int> v;
	v.push_back(10);
	v.push_back(40);
	v.push_back(30);
	v.push_back(40);
	v.push_back(20);
