#### 21.2.6 vector 互换容器

**函数原型**：`swap(vec);` //将 vec 与本身的元素互换

**示例**：

```c++
#include <iostream>
using namespace std;
#include <vector>

//1、基本使用
void test01()
{
	vector<int> v1;
	for (int i = 0; i < 10; i++)
	{
		v1.push_back(i);
	}

	vector<int> v2;
	for (int i = 10; i > 0; i--)
	{
		v2.push_back(i);
	}

	v1.swap(v2);
}

//2、实际用途:巧用swap可以收缩内存空间
void test02()
{
	vector<int> v;
	for (int i = 0; i < 100000; i++)
	{
		v.push_back(i);
	}

	cout << "v的容量为:" << v.capacity() << endl;
	cout << "v的大小为:" << v.size() << endl;

	v.resize(3); //重新指定大小

	cout << "v的容量为:" << v.capacity() << endl;
	cout << "v的大小为:" << v.size() << endl;

	//收缩内存
	vector<int>(v).swap(v); //匿名对象

	cout << "v的容量为:" << v.capacity() << endl;
	cout << "v的大小为:" << v.size() << endl;
}

int main() {

	test01();
	test02();

	system("pause");

	return 0;
}
```

#### 21.2.7 vector 预留空间

**函数原型**：`reserve(int len);` //容器预留 len 个元素长度，预留位置不初始化，元素不可访问

**示例**：

```c++
#include <iostream>
using namespace std;
#include <vector>

void test01()
{
	vector<int> v;

	//预留空间
	v.reserve(100000);

	int num = 0; //统计开辟次数
	int* p = NULL;
	for (int i = 0; i < 100000; i++)
	{
		v.push_back(i);
		if (p != &v[0])
		{
			p = &v[0];
			num++;
		}
	}

	cout << "num = " << num << endl;
}

int main() {

	test01();

	system("pause");

	return 0;
}
```

> 总结：如果数据量较大，可以一开始利用 reserve 预留空间。

### 21.3 deque 容器

**双端数组**，可以对头端进行插入删除操作。

deque 与 vector 区别：

* vector 对于头部的插入删除效率低，数据量越大，效率越低
* deque 相对而言，对头部的插入删除速度比 vector 快
* vector 访问元素时的速度会比 deque 快，这和两者内部实现有关

**deque 内部工作原理**：deque 内部有个**中控器**，维护每段缓冲区中的内容，缓冲区中存放真实数据，中控器维护的是每个缓冲区的地址，使得使用 deque 时像一片连续的内存空间。

#### 21.3.1 deque 构造函数

* `deque<T> deqT;` //默认构造
* `deque(beg, end);` //构造函数将 [beg， end) 区间中的元素拷贝给本身
* `deque(n, elem);` //构造函数将 n 个 elem 拷贝给本身
* `deque(const deque &deq);` //拷贝构造函数

**示例**：

```c++
#include <iostream>
using namespace std;
#include <deque>

void printDeque(const deque<int>& d)
{
	for (deque<int>::const_iterator it = d.begin(); it != d.end(); it++)
	{
		cout << *it << " ";
	}
	cout << endl;
}

void test01()
{
	deque<int> d1;
	for (int i = 0; i < 10; i++)
	{
		d1.push_back(i);
	}
	printDeque(d1);

	deque<int> d2(d1.begin(), d1.end());
	printDeque(d2);

	deque<int> d3(10, 100);
	printDeque(d3);

	deque<int> d4(d3);
	printDeque(d4);
}

int main() {

	test01();

	system("pause");

	return 0;
}
```

