	list<int> L1;
	L1.push_back(10);
	L1.push_back(20);

	list<int> L2;
	L2 = L1;

	list<int> L3;
	L3.assign(L2.begin(), L2.end());

	list<int> L4;
	L4.assign(10, 100);

	list<int> L5;
	L5.swap(L4);
}

int main() {

	test01();

	system("pause");

	return 0;
}
```

#### 21.7.3 list 大小操作

* `size();` //返回容器中元素的个数
* `empty();` //判断容器是否为空
* `resize(num);` //重新指定容器的长度为 num
* `resize(num, elem);` //重新指定容器的长度为 num，若变长则以 elem 填充

**示例**：

```c++
#include <iostream>
using namespace std;
#include <list>

void test01()
{
	list<int> L1;
	L1.push_back(10);
	L1.push_back(20);

	cout << "大小:" << L1.size() << endl;

	L1.resize(10, 100);
}

int main() {

	test01();

	system("pause");

	return 0;
}
```

#### 21.7.4 list 插入和删除

* `push_back(elem);` //在容器尾部添加一个元素
* `push_front(elem);` //在容器开头插入一个元素
* `pop_back();` //删除容器最后一个元素
* `pop_front();` //从容器开头移除第一个元素
* `insert(pos, elem);` //在 pos 位置插入 elem 元素的拷贝，返回新数据的位置
* `insert(pos, n, elem);` //在 pos 位置插入 n 个 elem 数据
* `insert(pos, beg, end);` //在 pos 位置插入 [beg， end) 区间的数据
* `erase(beg, end);` //删除 [beg， end) 区间的数据
* `erase(pos);` //删除 pos 位置的数据，返回下一个数据的位置
* `remove(elem);` //删除容器中所有与 elem 值匹配的元素
* `clear();` //移除容器的所有数据

**示例**：

```c++
#include <iostream>
using namespace std;
#include <list>

void test01()
{
	list<int> L;
	L.push_back(10);
	L.push_back(20);

	//头插
	L.push_front(100);

	//尾删
	L.pop_back();

	//头删
	L.pop_front();

	//插入
	L.insert(L.begin(), 1000);

	//删除
	list<int>::iterator it = L.begin();
	L.erase(++it);

	//移除匹配元素
	L.push_back(10000);
	L.push_back(10000);
	L.remove(10000);
}

int main() {

	test01();

	system("pause");

	return 0;
}
```

#### 21.7.5 list 数据存取

**函数原型**：

* `front();` //返回第一个元素
* `back();` //返回最后一个元素

**示例**：

```c++
#include <iostream>
using namespace std;
#include <list>

void test01()
{
	list<int> L;
	L.push_back(10);
	L.push_back(20);

	cout << "first = " << L.front() << endl;
	cout << "back = " << L.back() << endl;
}

int main() {

	test01();

	system("pause");

	return 0;
}
```

> 注意：list 容器的迭代器是双向迭代器，不支持随机访问，所以不支持 at 与 []。

#### 21.7.6 list 反转和排序

**函数原型**：

* `reverse();` //反转链表
* `sort();` //链表排序

**示例**：

```c++
#include <iostream>
using namespace std;
#include <list>
#include <algorithm>

void printList(const list<int>& L)
{
	for (list<int>::const_iterator it = L.begin(); it != L.end(); it++)
	{
		cout << *it << " ";
	}
	cout << endl;
}

bool myCompare(int val1, int val2)
{
	return val1 > val2;
}

void test01()
{
	list<int> L;
	L.push_back(90);
	L.push_back(30);
	L.push_back(20);
	L.push_back(70);
	printList(L);

	//反转容器的元素
	L.reverse();
	printList(L);

	//排序,默认从小到大
	L.sort();
	printList(L);

	//降序
	L.sort(myCompare);
	printList(L);
}

int main() {

	test01();

	system("pause");

	return 0;
}
```

> 注意：链表排序必须用成员函数 sort，不能直接用全局算法 sort，因为全局 sort 需要随机访问迭代器。

### 21.8 set 和 multiset 容器

**概念**：所有元素都会在插入时**自动被排序**。本质：**关联式容器，底层结构是用二叉树实现**。

**set 和 multiset 区别**：

* set 不允许容器中有重复的元素
* multiset 允许容器中有重复的元素

#### 21.8.1 set 构造和赋值

* `set<T> st;` //默认构造函数
* `set(const set &st);` //拷贝构造函数
* `set& operator=(const set &st);` //重载等号操作符

**示例**：

```c++
#include <iostream>
using namespace std;
#include <set>

void printSet(set<int>& s)
{
	for (set<int>::iterator it = s.begin(); it != s.end(); it++)
	{
		cout << *it << " ";
	}
	cout << endl;
}

void test01()
{
	set<int> s1;
	s1.insert(10);
	s1.insert(30);
	s1.insert(20);
	s1.insert(40);
	printSet(s1);

	//拷贝构造
	set<int> s2(s1);
	printSet(s2);

	//赋值
	set<int> s3;
	s3 = s2;
	printSet(s3);
}

int main() {

	test01();

	system("pause");

	return 0;
}
```

#### 21.8.2 set 大小和交换

* `size();`
* `empty();`
* `swap(st);`

**示例**：

```c++
#include <iostream>
using namespace std;
#include <set>

void test01()
{
	set<int> s1;
	s1.insert(10);
	s1.insert(20);

	set<int> s2;
	s2.insert(100);
	s2.insert(200);

	s1.swap(s2);
}

int main() {

	test01();

	system("pause");

	return 0;
}
```

#### 21.8.3 set 插入和删除

* `insert(elem);` //在容器中插入元素
* `clear();` //清除所有元素
* `erase(pos);` //删除 pos 迭代器所指的元素，返回下一个元素的迭代器
* `erase(beg, end);` //删除区间 [beg， end) 的所有元素
* `erase(elem);` //删除容器中值为 elem 的元素

**示例**：

```c++
#include <iostream>
using namespace std;
#include <set>

void test01()
{
	set<int> s;
	s.insert(10);
	s.insert(20);
	s.insert(30);

	//删除
	s.erase(s.begin());

	//删除区间
	s.erase(s.begin(), s.end());

	s.clear();
}

int main() {

	test01();

	system("pause");

	return 0;
}
```

#### 21.8.4 set 查找和统计

* `find(key);` //查找 key 是否存在，若存在，返回该键的元素的迭代器；若不存在，返回 set.end()
* `count(key);` //统计 key 的元素个数(set 中只能是 0 或 1)

**示例**：

```c++
#include <iostream>
using namespace std;
#include <set>

void test01()
{
	set<int> s;
	s.insert(10);
	s.insert(20);
	s.insert(30);

	set<int>::iterator pos = s.find(30);

	if (pos != s.end())
	{
		cout << "找到元素:" << *pos << endl;
	}
	else
	{
		cout << "未找到元素" << endl;
	}

	cout << "count(20) = " << s.count(20) << endl;
}

int main() {

	test01();

	system("pause");

	return 0;
}
```

#### 21.8.5 set 与 multiset 区别

**示例**：set 插入时用 pair 判断是否成功，multiset 允许重复

```c++
#include <iostream>
using namespace std;
#include <set>

void test01()
{
	set<int> s;
	//insert 返回 pair<iterator, bool>
	pair<set<int>::iterator, bool> ret = s.insert(10);

	if (ret.second)
	{
		cout << "第一次插入成功" << endl;
	}
	else
	{
		cout << "第一次插入失败" << endl;
	}

	ret = s.insert(10);
	if (ret.second)
	{
		cout << "第二次插入成功" << endl;
	}
	else
	{
		cout << "第二次插入失败" << endl;
	}
}

void test02()
{
	multiset<int> ms;
	//multiset 允许插入重复值
	ms.insert(10);
	ms.insert(10);
	ms.insert(10);
}

int main() {

	test01();
	test02();

	system("pause");

	return 0;
}
```

#### 21.8.6 pair 对组

**概念**：成对出现的数据，利用对组可以返回两个数据。

**两种创建方式**：

* `pair<type, type> p ( value1, value2 );`
* `pair<type, type> p = make_pair( value1, value2 );`

**示例**：

```c++
#include <iostream>
using namespace std;
#include <string>

void test01()
{
	//第一种方式
	pair<string, int> p(string("Tom"), 20);
	cout << "姓名: " << p.first << " 年龄: " << p.second << endl;

	//第二种方式
	pair<string, int> p2 = make_pair("Jerry", 10);
	cout << "姓名: " << p2.first << " 年龄: " << p2.second << endl;
}

int main() {

	test01();

	system("pause");

	return 0;
}
```

### 21.9 map 和 multimap 容器

**概念**：

* map 中所有元素都是 **pair**
* pair 中第一个元素为 **key**(键值)，第二个元素为 **value**(实值)
* **所有元素都会根据元素的键值自动排序**

**本质**：map/multimap 属于**关联式容器**，底层结构是用**二叉树**实现。

**优点**：可以根据 key 值快速找到 value 值。

**map 和 multimap 区别**：

* map 不允许容器中有重复 key 值元素
* multimap 允许容器中有重复 key 值元素

#### 21.9.1 map 构造和赋值

* `map<T1, T2> mp;`
* `map(const map &mp);`
* `map& operator=(const map &mp);`

**示例**：

```c++
#include <iostream>
using namespace std;
#include <map>

void printMap(map<int, int>& m)
{
	for (map<int, int>::iterator it = m.begin(); it != m.end(); it++)
	{
		cout << "key = " << it->first << " value = " << it->second << endl;
	}
}

void test01()
{
	map<int, int> m;
	m.insert(pair<int, int>(1, 10));
	m.insert(pair<int, int>(3, 30));
	m.insert(pair<int, int>(2, 20));
	m.insert(pair<int, int>(4, 40));
	printMap(m);

	//拷贝构造
	map<int, int> m2(m);
	printMap(m2);

	//赋值
	map<int, int> m3;
	m3 = m2;
	printMap(m3);
}

int main() {

	test01();

	system("pause");

	return 0;
}
```

#### 21.9.2 map 大小和交换

* `size();`
* `empty();`
* `swap(st);`

**示例**：

```c++
#include <iostream>
using namespace std;
#include <map>

void test01()
{
	map<int, int> m;
	m.insert(pair<int, int>(1, 10));
	m.insert(pair<int, int>(2, 20));

	map<int, int> m2;
	m2.insert(pair<int, int>(3, 30));

	m2.swap(m);
}

int main() {

	test01();

	system("pause");

	return 0;
}
```

#### 21.9.3 map 插入和删除

**函数原型**：

* `insert(elem);` //在容器中插入元素
* `clear();` //清除所有元素
* `erase(pos);` //删除 pos 迭代器所指的元素，返回下一个元素的迭代器
* `erase(beg, end);` //删除区间 [beg， end) 的所有元素
* `erase(key);` //删除容器中值为 key 的元素

**示例**：

```c++
#include <iostream>
using namespace std;
#include <map>

void test01()
{
	map<int, int> m;

	//第一种插入方式
	m.insert(pair<int, int>(1, 10));
	//第二种插入方式
	m.insert(make_pair(2, 20));
	//第三种插入方式
	m.insert(map<int, int>::value_type(3, 30));
	//第四种插入方式:[] 不建议用它插入
	m[4] = 40;

	//删除
	m.erase(m.begin());
	m.erase(3);

	//清空
	m.erase(m.begin(), m.end());
	m.clear();
}

int main() {

	test01();

	system("pause");

	return 0;
}
```

#### 21.9.4 map 查找和统计

* `find(key);` //查找 key 是否存在，若存在返回该键的元素的迭代器；若不存在返回 map.end()
* `count(key);` //统计 key 的元素个数

**示例**：

```c++
#include <iostream>
using namespace std;
#include <map>

void test01()
{
	map<int, int> m;
	m.insert(pair<int, int>(1, 10));
	m.insert(pair<int, int>(2, 20));

	map<int, int>::iterator pos = m.find(2);

	if (pos != m.end())
	{
		cout << "找到元素 key = " << (*pos).first << " value = " << (*pos).second << endl;
	}
	else
	{
		cout << "未找到元素" << endl;
	}

	//统计 map 中 count 只能是 0 或 1
	cout << "count = " << m.count(2) << endl;
}

int main() {

	test01();

	system("pause");

	return 0;
}
```

> 总结：STL 常用容器各有所长——string 处理文本，vector 访问快，deque 双端灵活，list 插入删除快，set/map 有序，stack/queue 各有纪律，实际使用按场景取舍。

