	//new Base; //错误,抽象类无法实例化对象

	//子类必须重写父类中的纯虚函数,否则无法实例化对象
	Son s;
	s.func();
}

int main() {

	test01();

	system("pause");

	return 0;
}
```

### 17.4 多态案例二：制作饮品

制作饮品的流程大体为：煮水 → 冲泡 → 倒入杯中 → 加入辅料。

利用多态技术实现，提供抽象制作饮品基类，提供子类制作咖啡和茶叶。

**示例**：

```c++
#include <iostream>
using namespace std;

//抽象制作饮品
class AbstractDrinking
{
public:

	//烧水
	virtual void Boil() = 0;

	//冲泡
	virtual void Brew() = 0;

	//倒入杯中
	virtual void PourInCup() = 0;

	//加入辅料
	virtual void PutSomething() = 0;

	//规定流程
	void MakeDrink()
	{
		Boil();
		Brew();
		PourInCup();
		PutSomething();
	}
};

//制作咖啡
class Coffee : public AbstractDrinking
{
public:

	//烧水
	void Boil()
	{
		cout << "煮农夫山泉" << endl;
	}

	//冲泡
	void Brew()
	{
		cout << "冲泡咖啡" << endl;
	}

	//倒入杯中
	void PourInCup()
	{
		cout << "倒入杯中" << endl;
	}

	//加入辅料
	void PutSomething()
	{
		cout << "加入糖和牛奶" << endl;
	}
};

//制作茶叶
class Tea : public AbstractDrinking
{
public:

	//烧水
	void Boil()
	{
		cout << "煮矿泉水" << endl;
	}

	//冲泡
	void Brew()
	{
		cout << "冲泡茶叶" << endl;
	}

	//倒入杯中
	void PourInCup()
	{
		cout << "倒入杯中" << endl;
	}

	//加入辅料
	void PutSomething()
	{
		cout << "加入枸杞" << endl;
	}
};

//制作饮品函数
void doWork(AbstractDrinking* abs)
{
	abs->MakeDrink();
	delete abs; //释放
}

void test01()
{
	//制作咖啡
	doWork(new Coffee);

	cout << "----------------------" << endl;

	//制作茶叶
	doWork(new Tea);
}

int main() {

	test01();

	system("pause");

	return 0;
}
```

### 17.5 虚析构和纯虚析构

多态使用时，**如果子类中有属性开辟到堆区，那么父类指针在释放时无法调用到子类的析构代码**，会造成内存泄漏。

解决办法：将父类中的析构函数改为**虚析构**或者**纯虚析构**。

**虚析构语法**：`virtual ~类名(){}`

**纯虚析构语法**：`virtual ~类名() = 0;`，且需要类外实现 `类名::~类名(){}`

**示例**：

```c++
#include <iostream>
using namespace std;
#include <string>

class Animal
{
public:

	Animal()
	{
		cout << "Animal 构造函数调用" << endl;
	}

	//纯虚析构
	//有了纯虚析构之后,这个类也属于抽象类,无法实例化对象
	virtual ~Animal() = 0;
};

//纯虚析构需要类外实现
Animal::~Animal()
{
	cout << "Animal 纯虚析构函数调用" << endl;
}

class Cat : public Animal
{
public:

	Cat(string name)
	{
		cout << "Cat 构造函数调用" << endl;
		m_Name = new string(name);
	}

	~Cat()
	{
		if (m_Name != NULL)
		{
			cout << "Cat 析构函数调用" << endl;
			delete m_Name;
			m_Name = NULL;
		}
	}

	string* m_Name;
};

void test01()
{
	Animal* animal = new Cat("Tom");
	cout << *animal->m_Name << endl;

	//父类指针在析构时,不会调用子类中析构函数
	//导致子类如果有堆区属性,会出现内存泄漏
	//解决办法:父类析构函数改为虚析构或纯虚析构
	delete animal;
}

int main() {

	test01();

	system("pause");

	return 0;
}
```

> 总结：
> * 虚析构或纯虚析构就是用来解决通过父类指针释放子类对象的问题
> * 如果子类中没有堆区数据，可以不写虚析构或纯虚析构
> * 拥有纯虚析构函数的类也属于抽象类

