	Person(string name, int age)
	{
		this->m_Name = name;
		this->m_Age = age;
	}

	//重载 == 号
	bool operator==(Person& p)
	{
		if (this->m_Name == p.m_Name && this->m_Age == p.m_Age)
		{
			return true;
		}
		return false;
	}

	//重载 != 号
	bool operator!=(Person& p)
	{
		if (this->m_Name == p.m_Name && this->m_Age == p.m_Age)
		{
			return false;
		}
		return true;
	}

	string m_Name;
	int m_Age;
};

void test01()
{
	Person a("孙悟空", 18);
	Person b("孙悟空", 18);

	if (a == b)
	{
		cout << "a和b相等" << endl;
	}
	else
	{
		cout << "a和b不相等" << endl;
	}

	if (a != b)
	{
		cout << "a和b不相等" << endl;
	}
	else
	{
		cout << "a和b相等" << endl;
	}
}

int main() {

	test01();

	system("pause");

	return 0;
}
```

### 15.6 函数调用运算符重载

**作用**：

* 函数调用运算符 `()` 也可以重载
* 由于重载后使用的方式非常像函数的调用，因此称为**仿函数**
* 仿函数没有固定写法，非常灵活

**示例**：

```c++
#include <iostream>
using namespace std;
#include <string>

class MyPrint
{
public:

	void operator()(string text)
	{
		cout << text << endl;
	}
};

class MyAdd
{
public:

	int operator()(int v1, int v2)
	{
		return v1 + v2;
	}
};

void test01()
{
	//重载的 () 操作符也称为仿函数
	MyPrint myFunc;
	myFunc("hello world");
}

void test02()
{
	MyAdd add;
	int ret = add(10, 10);
	cout << "ret = " << ret << endl;

	//匿名对象调用
	cout << "MyAdd()(100, 100) = " << MyAdd()(100, 100) << endl;
}

int main() {

	test01();
	test02();

	system("pause");

	return 0;
}
```

> 总结：函数调用运算符重载让对象的行为像函数，这种对象称为仿函数，在 STL 中会大量遇到。

